// === Tab: Node ===
class Node {
	constructor(ang, name, freq, col, pos, ktype) {
		this.ang = ang;
		this.name = name;
		this.freq = freq;
		this.glow = 180;
		this.tglow = 180;
		this.col = col;
		this.pos = pos;
		this.type = ktype;
	}
	show() {
		this.glow = lerp(this.glow, this.tglow, 0.05);
		push();
		let x = cos(this.ang) * dim / 2;
		let y = sin(this.ang) * dim / 2;
		strokeWeight(dim / 28);
		stroke(this.col, 360, 360, 330);
		point(x, y);
		noStroke();
		fill(this.col, 0, 360);
		let tx = cos(this.ang) * dim / 1.8;
		let ty = sin(this.ang) * dim / 1.8;
		textAlign(CENTER, CENTER);
		textSize(dim * this.glow / 3200);
		text(this.name, tx, ty);
		pop();
		push();
		translate((this.pos - 6) * dim / 28, -dim / 36);
		noStroke();
		fill(this.col, 300, this.glow);
		if (this.type == 3) {
			translate(0, -dim / 40);
			fill(this.col, 2 * (this.glow - 180), 2 * (this.glow - 180))
			rect(0, 0, dim / 24, dim / 10, 0, 0, dim / 80, dim / 80);
		} else {
			translate(0, dim / 40);
			fill(this.col, 2 * (this.glow - 180), 360, 330);
			rect(0, 0, dim / 15, dim / 5, 0, 0, dim / 80, dim / 80);
		}
		pop();
	}
}

// === Tab: Plucker ===
class Plucker {
	constructor(ang) {
		this.ang = ang;
		this.col = 0;
		this.sat = 0;
	}
	advance() {
		this.ang += aspeed;
		if (this.ang < 0) this.ang += 360;
		if (this.ang > 360) this.ang -= 360;
		this.sat = lerp(this.sat, 0, 0.02);
	}
}

// === Tab: mySketch ===
// For the #WCCChallenge, theme: "downward spiral"
// This isn't a spiral, per se, but it's round, and there's a downward progression of notes
// for some shapes and rotations, especially the pentagon (clockwise) and heptagon (counterclockwise)!
// Inspired by the YouTuber AlgoMotion, who makes amazing videos on CS and music:
// https://www.youtube.com/watch?v=V0YH8M6C-VM

var dim;
var pts = 0;
var notenames = ['C', 'G', 'D', 'A', 'E', 'B', 'G♭', 'D♭', 'Ab', 'E♭', 'B♭', 'F'];
var notefreqs = ['C1', 'G1', 'D1', 'A1', 'E1', 'B1', 'F#1', 'C#1', 'G#1', 'D#1', 'A#1', 'F1'];
var scalepos = [0, 7, 2, 9, 4, 11, 6, 1, 8, 3, 10, 5];
var keytypes = [0, 3, 1, 3, 2, 0, 3, 1, 3, 1, 3, 2];
var pnames = ['triangle', 'square', 'pentagon', 'hexagon', 'heptagon', 'octagon', 'nonagon', 'decagon', 'hendecagon', 'dodecagon'];
var nodes = [];
var pluckers = [];
var index = 0;
var aspeed = 0;
var sampler;
var started = false;
var octave = 1;

function preload() {
	sampler = new Tone.Sampler({
		urls: {
			C2: 'CPiano2.wav',
		}
	}).toDestination();
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	angleMode(DEGREES);
	dim = 0.8 * height;
	colorMode(HSB, 360);
	rectMode(CENTER);
	makeNodes();
	makePluckers();
	sampler.volume.value = -20;
}

function mouseClicked() {
	if (!started) {
		started = true;
		nodes[0].glow = 360
		sampler.triggerAttack(nodes[0].freq).toDestination();
	} else {
		pts = (pts + 1) % 10;
		makePluckers();
	}
}

function draw() {
	if (started) aspeed = lerp(aspeed, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), width / 4, 3 * width / 4, -0.5, 0.5, true), 0.2);
	background(0);
	translate(width / 2, height / 2);
	stroke(0, 0, 180);
	strokeWeight(dim / 100);
	noFill();
	ellipse(0, 0, dim);
	if (started) {
		stroke(0, 0, 360, 300);
		strokeWeight(dim / 100);
		noFill();
		polygon(dim / 2.05);
	}
	for (n of nodes) {
		n.show();
	}
	fill(0, 0, 360);
	textSize(dim / 15);
	noStroke();
	textAlign(CENTER, CENTER);
	if (!started) text('click to start!', 0, dim / 7)
	else text(pnames[pts], 0, dim / 7)
	for (p of pluckers) {
		for (n of nodes) {
			if ((abs((n.ang - p.ang) % 360) < 0.5 || abs((n.ang - p.ang) % 360) > 359.5) && n.glow < 200) {
				n.glow = 360;
				p.col = n.col
				p.sat = 360
				sampler.triggerAttack(n.freq).toDestination();
			}
		}
	}
	for (p of pluckers) {
		p.advance();
	}
}

function polygon(radius) {
	push();
	beginShape();
	for (p of pluckers) {
		let sx = radius * cos(p.ang);
		let sy = radius * sin(p.ang);
		vertex(sx, sy);
	}
	endShape(CLOSE);

	for (p of pluckers) {
		let sx = radius * cos(p.ang);
		let sy = radius * sin(p.ang);
		stroke(p.col, p.sat, 360, 330)
		beginShape();
		vertex(sx, sy);
		vertex(sx, sy);
		curveVertex((radius / 1.8) * cos(p.ang + aspeed * 30), (radius / 1.8) * sin(p.ang + aspeed * 30));
		vertex(0, 0);
		vertex(0, 0);
		endShape();
	}
	pop();
}

function makeNodes() {
	for (i = 0; i < notenames.length; i++) {
		let ang = i * 30 + 270;
		let name = notenames[i];
		let freq = notefreqs[i];
		let pos = scalepos[i];
		if (scalepos[i] > 4) pos += 1
		let col = scalepos[i] * 30;
		let ktype = keytypes[scalepos[i]];
		let node = new Node(ang, name, freq, col, pos, ktype);
		nodes.push(node);
		nodes.sort(function(a, b) {
			return a.type - b.type;
		});
	}
}

function makePluckers() {
	pluckers = [];
	for (i = 0; i < (3 + pts); i += 1) {
		let ang = i * 360 / (3 + pts)
		ang -= 105;
		ang = ang % 360
		let plucker = new Plucker(ang);
		pluckers.push(plucker);
	}
}
